package com.agacostays.billing.mapper; import com.agacostays.billing.entity.Invoice;import com.agacostays.billing.dto.response.InvoiceResponse;import org.springframework.stereotype.Component; @Component public class InvoiceMapper{public InvoiceResponse toResponse(Invoice i){return new InvoiceResponse(i.getInvoiceId(),i.getBillId(),i.getInvoiceNumber(),i.getInvoiceStatus().name(),i.getInvoiceUrl(),i.getGeneratedAt());}}
